import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {
    private static final int MOD = 998244353;
    public static void main(String[] args) throws Exception {
        InputReader in = new InputReader();
        PrintWriter out = new PrintWriter(System.out);
        int n = in.nextInt();
        long k = in.nextLong();
        int maxN = 200001;
        long[] fact = new long[maxN];
        long[] invFact = new long[maxN];
        fact[0] = invFact[0] = 1;
        for (int i = 1; i < maxN; i++) {
            fact[i] = fact[i-1] * i % MOD;
            invFact[i] = invFact[i-1] * power(i, MOD-2) % MOD;
        }
        if (k >= n) {
            out.println(0);
        } else if (k == 0) {
            out.println(fact[n]);
        } else {
            int m = (int)(n - k);
            long sum = 0;
            for (int i = 0; i <= m; i++) {
                long val = nCr(m, i, fact, invFact) * power(m - i, n) % MOD;
                if ((i & 1) == 0) sum = (sum + val) % MOD;
                else sum = (sum - val + MOD) % MOD;
            }
            long answer = 2 * fact[n] % MOD * invFact[n - m] % MOD * sum % MOD * invFact[m] % MOD;
            out.println(answer);
        }
        out.close();
    }
    static long power(long base, long exp) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) result = result * base % MOD;
            base = base * base % MOD;
            exp >>= 1;
        }
        return result;
    }
    static long nCr(int n, int r, long[] fact, long[] invFact) {
        return fact[n] * invFact[r] % MOD * invFact[n - r] % MOD;
    }
    static class InputReader {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;
        String next() throws Exception {
            while (st == null || !st.hasMoreTokens()) st = new StringTokenizer(br.readLine());
            return st.nextToken();
        }
        int nextInt() throws Exception { return Integer.parseInt(next()); }
        long nextLong() throws Exception { return Long.parseLong(next()); }
    }
}
